//! The depth bound, and the things that would quietly remove it.

use super::*;

#[test]
fn a_sub_agent_has_no_way_to_spawn_another() {
    // This is the depth bound. Not a counter that a future edit forgets to
    // thread through, but the absence of anywhere to ask from: the schema a
    // sub-agent answers offers neither questions nor lookups.
    let schema = answer_schema();
    let properties = schema["properties"].as_object().unwrap();
    assert!(!properties.contains_key("questions"));
    assert!(!properties.contains_key("lookups"));
    assert_eq!(schema["additionalProperties"], json!(false));
}

#[test]
fn a_sub_agent_runs_on_the_model_it_was_given_with_the_answer_system() {
    let call = answer_call("vendor/flash", 2, "Does the caller validate?", "diff");
    assert_eq!(call.model, "vendor/flash");
    assert_eq!(call.id, "answer_2");
    assert_eq!(call.system, ANSWER_SYSTEM);
    assert_eq!(call.schema_name, "tinysweeper_subagent_answer");
    assert!(call.prompt.starts_with("diff"));
    assert!(call.prompt.contains("Does the caller validate?"));
}

#[test]
fn the_question_schema_caps_how_many_may_be_asked() {
    // Without the cap a panellist stops reviewing the diff and starts
    // exploring the repository, and the answers arrive too late to be worth it.
    assert_eq!(
        questions_schema()["maxItems"],
        json!(MAX_QUESTIONS_PER_REVIEWER)
    );
}

#[test]
fn a_sub_agent_is_told_it_may_not_reach_a_verdict() {
    // Its output is evidence for the verify round. Evidence that has already
    // made up its mind is worth less than none.
    assert!(ANSWER_SYSTEM.contains("not reviewing"));
    assert!(ANSWER_SYSTEM.contains("do not report problems"));
}

#[test]
fn an_answer_may_be_an_admission_that_the_evidence_does_not_say() {
    let schema = answer_schema();
    assert_eq!(schema["required"], json!(["answer", "confident"]));
}

#[test]
fn an_unconfident_answer_is_rendered_as_such_rather_than_dropped() {
    // "The evidence does not say" is a real input to whether a finding
    // survives: it is the difference between a verifier confirming a claim and
    // a verifier having had no way to check it.
    let rendered = render(&[Answered {
        question: "Does the caller validate this?".into(),
        answer: "No caller is visible in the supplied evidence.".into(),
        confident: false,
    }]);

    assert!(rendered.contains("did not settle"), "{rendered}");
    assert!(rendered.contains("No caller is visible"), "{rendered}");
}

#[test]
fn a_confident_answer_carries_no_caveat() {
    let rendered = render(&[Answered {
        question: "Does the caller validate this?".into(),
        answer: "Yes, `parse` rejects empty input at line 10.".into(),
        confident: true,
    }]);

    assert!(!rendered.contains("did not settle"), "{rendered}");
}

#[test]
fn nothing_asked_renders_to_nothing() {
    // An empty block in the prompt is not free: it is prompt suffix, and this
    // lane's whole caching story is about what the suffix contains.
    assert!(render(&[]).is_empty());
}

#[test]
fn a_schema_with_no_properties_still_gains_the_questions_key() {
    // The silent-no-op case. The instruction and the schema are set together,
    // so a schema returned unchanged means a reviewer invited to ask a question
    // it has nowhere to write — rejected under strict mode, dropped under
    // `json_object`, and in both cases the follow-up turn never happens.
    let widened = with_questions(json!({ "type": "object" }));
    assert!(widened["properties"]["questions"].is_object());
}

#[test]
fn widening_a_schema_leaves_its_own_contract_alone() {
    let widened = with_questions(json!({
        "type": "object",
        "additionalProperties": false,
        "required": ["summary"],
        "properties": { "summary": { "type": "string" } }
    }));

    // Optional: a reviewer with nothing to ask answers the schema it always did.
    assert_eq!(widened["required"], json!(["summary"]));
    assert!(widened["properties"]["summary"].is_object());
    assert!(widened["properties"]["questions"].is_object());
}

//! Offline factory identity and capability selection tests.

use std::sync::Arc;

use super::model_factory::{ModelFactory, ModelPurpose, StaticModelFactory};
use crate::harness::MockModel;
use crate::ports::model::Model;

#[tokio::test]
async fn static_factory_reuses_the_supplied_text_and_vision_models() {
    let text: Arc<dyn Model> = Arc::new(MockModel::silent());
    let vision: Arc<dyn Model> = Arc::new(MockModel::silent());
    let factory = StaticModelFactory::new(text.clone()).with_vision(vision.clone());
    let models = crate::config::Config::default().models;
    for _ in 0..2 {
        assert!(Arc::ptr_eq(
            &factory.create(&models, ModelPurpose::Text).await.unwrap(),
            &text
        ));
        assert!(Arc::ptr_eq(
            &factory.create(&models, ModelPurpose::Vision).await.unwrap(),
            &vision
        ));
    }
}

#[tokio::test]
async fn missing_vision_never_silently_uses_the_text_model() {
    let factory = StaticModelFactory::new(Arc::new(MockModel::silent()));
    let error = match factory
        .create(
            &crate::config::Config::default().models,
            ModelPurpose::Vision,
        )
        .await
    {
        Ok(_) => panic!("vision unexpectedly resolved"),
        Err(error) => error,
    };
    assert!(matches!(error, crate::error::Error::Model(_)));
}

//! Agentic runner evidence and default completion compatibility.

use super::*;
use crate::config::types::Config;
use crate::ports::model::{ModelRequest, ModelResponse};
use crate::ports::tree::MockTree;
use async_trait::async_trait;
use serde_json::json;

struct Exploring;
#[async_trait]
impl Model for Exploring {
    async fn complete(&self, request: ModelRequest) -> Result<ModelResponse> {
        Ok(ModelResponse {
            value: json!({"summary":"completion"}),
            model: request.model,
            usage: Usage::default(),
        })
    }
    async fn review(
        &self,
        request: ModelRequest,
        tree: &dyn TreeReader,
        _: &LookupPolicy,
    ) -> Result<ModelResponse> {
        assert!(
            request
                .schema
                .get("properties")
                .and_then(|p| p.get("lookups"))
                .is_none()
        );
        assert!(
            !request.messages[0]
                .content
                .contains("This is your last turn")
        );
        tree.lookup(&Lookup::Read {
            path: "src/config.rs".into(),
            start: Some(1),
            end: Some(2),
        })
        .await?;
        Ok(ModelResponse {
            value: json!({"summary":"explored"}),
            model: request.model,
            usage: Usage::default(),
        })
    }
}
#[tokio::test]
async fn opted_in_review_preserves_tool_evidence_without_changing_disabled_behavior() {
    let key = format!("AKIA{}", "IOSFODNN7EXAMPLE");
    let tree = MockTree::from_files([(
        "src/config.rs",
        format!("KEY=\"{key}\"\nlet visible = true;"),
    )]);
    let calls = [Call {
        id: "reviewer".into(),
        model: "fixture".into(),
        system: "review".into(),
        prompt: "diff evidence".into(),
        schema_name: "review".into(),
    }];
    let policy = LookupPolicy::default();
    let mut config = Config::default();
    config.models.agentic_reviewers = true;
    let answer = ask_all(
        lane_llm(Arc::new(Exploring), &config, 1.0),
        LaneId::Critique,
        &calls,
        &json!({"type":"object"}),
        Asking {
            tree: Some(&tree),
            lookup: Some(&policy),
            ..Asking::default()
        },
    )
    .await
    .unwrap()
    .remove(0);
    assert_eq!(answer.value.unwrap()["summary"], "explored");
    assert!(answer.looked_up.contains("let visible = true"));
    assert!(!answer.looked_up.contains(&key));
    config.models.agentic_reviewers = false;
    let answer = ask_all(
        lane_llm(Arc::new(Exploring), &config, 1.0),
        LaneId::Critique,
        &calls,
        &json!({"type":"object"}),
        Asking {
            tree: Some(&tree),
            lookup: Some(&policy),
            ..Asking::default()
        },
    )
    .await
    .unwrap()
    .remove(0);
    assert_eq!(answer.value.unwrap()["summary"], "completion");
    assert!(answer.looked_up.is_empty());
}

//! Server-owned model resolution and reuse without credentials or network.

use std::sync::Mutex;

use super::*;
use crate::config::types::Models;
use crate::harness::MockModel;
use crate::ports::model_factory::StaticModelFactory;

struct RecordingFactory {
    delegate: StaticModelFactory,
    calls: Mutex<Vec<ModelPurpose>>,
    fail: Option<ModelPurpose>,
}

#[async_trait::async_trait]
impl ModelFactory for RecordingFactory {
    async fn create(&self, models: &Models, purpose: ModelPurpose) -> Result<Arc<dyn Model>> {
        self.calls.lock().unwrap().push(purpose);
        if self.fail == Some(purpose) {
            return Err(crate::error::Error::Model("factory unavailable".into()));
        }
        self.delegate.create(models, purpose).await
    }
}

fn factory() -> RecordingFactory {
    RecordingFactory {
        delegate: StaticModelFactory::new(Arc::new(MockModel::silent()))
            .with_vision(Arc::new(MockModel::silent())),
        calls: Mutex::new(vec![]),
        fail: None,
    }
}

#[tokio::test]
async fn text_model_is_resolved_once_and_reused_across_worker_clones_and_captions() {
    let factory = factory();
    let config = Config::default();
    let models = ResolvedModels::resolve(&factory, &config).await.unwrap();
    let worker = models.clone();
    assert!(Arc::ptr_eq(&models.text(), &worker.text()));
    let (caption, id, vision) = worker.caption(&config);
    assert!(Arc::ptr_eq(&models.text(), &caption));
    assert_eq!(
        id,
        config.model_for_workload(crate::config::types::Workload::Preview)
    );
    assert!(!vision);
    assert_eq!(*factory.calls.lock().unwrap(), vec![ModelPurpose::Text]);
}

#[tokio::test]
async fn configured_vision_has_its_own_reused_handle_and_trimmed_model_id() {
    let factory = factory();
    let mut config = Config::default();
    config.models.vision = Some("  vendor/vision  ".into());
    let models = ResolvedModels::resolve(&factory, &config).await.unwrap();
    let worker = models.clone();
    let (first, id, vision) = models.caption(&config);
    let (second, _, _) = worker.caption(&config);
    assert_eq!(id, "vendor/vision");
    assert!(vision);
    assert!(Arc::ptr_eq(&first, &second));
    assert!(!Arc::ptr_eq(&first, &models.text()));
    assert_eq!(
        *factory.calls.lock().unwrap(),
        vec![ModelPurpose::Text, ModelPurpose::Vision]
    );
}

#[tokio::test]
async fn blank_vision_uses_text_and_does_not_construct_a_vision_adapter() {
    let factory = factory();
    let mut config = Config::default();
    config.models.vision = Some("  ".into());
    let models = ResolvedModels::resolve(&factory, &config).await.unwrap();
    assert!(!models.caption(&config).2);
    assert_eq!(*factory.calls.lock().unwrap(), vec![ModelPurpose::Text]);
}

#[tokio::test]
async fn failed_text_or_configured_vision_resolution_refuses_startup() {
    for purpose in [ModelPurpose::Text, ModelPurpose::Vision] {
        let mut factory = factory();
        factory.fail = Some(purpose);
        let mut config = Config::default();
        config.models.vision = Some("vendor/vision".into());
        let error = match ResolvedModels::resolve(&factory, &config).await {
            Ok(_) => panic!("failed factory produced models"),
            Err(error) => error,
        };
        assert!(matches!(error, crate::error::Error::Model(_)));
    }
}
